test("below", () => { assert.equal(clamp(-5, 0, 10), 0); });
test("above", () => { assert.equal(clamp(15, 0, 10), 10); });
test("at low", () => { assert.equal(clamp(0, 0, 10), 0); });
test("at high", () => { assert.equal(clamp(10, 0, 10), 10); });
```
